<?php if(!empty($banners) && count($banners)>1): ?><script>(()=>{const root=document.querySelector('[data-banner-carousel]');if(!root)return;const slides=[...root.querySelectorAll('[data-banner-slide]')],dots=[...root.querySelectorAll('[data-banner-dot]')];if(slides.length<2)return;const reduced=window.matchMedia('(prefers-reduced-motion: reduce)').matches;let current=0,timer=0,hovered=false,focused=false;function show(index){current=(index+slides.length)%slides.length;slides.forEach((slide,i)=>{const active=i===current;slide.classList.toggle('is-active',active);slide.setAttribute('aria-hidden',String(!active));const link=slide.querySelector('a');if(link)link.tabIndex=active?0:-1});dots.forEach((dot,i)=>dot.setAttribute('aria-current',String(i===current)))}function stop(){window.clearInterval(timer);timer=0}function start(){stop();if(!reduced&&!hovered&&!focused&&!document.hidden)timer=window.setInterval(()=>show(current+1),6000)}root.addEventListener('mouseenter',()=>{hovered=true;stop()});root.addEventListener('mouseleave',()=>{hovered=false;start()});root.addEventListener('focusin',()=>{focused=true;stop()});root.addEventListener('focusout',event=>{if(!root.contains(event.relatedTarget)){focused=false;start()}});root.querySelector('[data-banner-prev]')?.addEventListener('click',()=>{show(current-1);start()});root.querySelector('[data-banner-next]')?.addEventListener('click',()=>{show(current+1);start()});dots.forEach(dot=>dot.addEventListener('click',()=>{show(Number(dot.dataset.bannerDot));start()}));document.addEventListener('visibilitychange',()=>start());start()})();</script><?php endif; ?>
